#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> parent, sizes;

int findRoot(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

bool unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return false;
    if (sizes[a] < sizes[b]) swap(a, b);
    parent[b] = a;
    sizes[a] += sizes[b];
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long k;
    cin >> k;
    vector<string> eq(k);
    for (int i = 0; i < k; i++) cin >> eq[i];

    parent.resize(26);
    sizes.assign(26, 1);
    for (int v = 0; v < 26; v++) parent[v] = v;
    for (const string& e : eq) {
        if (e[1] == '=') unite(e[0] - 'a', e[3] - 'a');
    }
    bool ok = true;
    for (const string& e : eq) {
        if (e[1] == '!' && findRoot(e[0] - 'a') == findRoot(e[3] - 'a')) ok = false;
    }
    cout << (ok ? "yes" : "no") << "\n";

    return 0;
}

