import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int[] parent;
    static int[] sizes;

    static int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    static boolean unite(int a, int b) {
        a = findRoot(a);
        b = findRoot(b);
        if (a == b) return false;
        if (sizes[a] < sizes[b]) {
            int t = a;
            a = b;
            b = t;
        }
        parent[b] = a;
        sizes[a] += sizes[b];
        return true;
    }

    public static void main(String[] args) throws IOException {
        long k = Long.parseLong(next());
        String[] eq = new String[(int) k];
        for (int i = 0; i < eq.length; i++) eq[i] = next();

        parent = new int[26];
        sizes = new int[26];
        for (int v = 0; v < 26; v++) {
            parent[v] = v;
            sizes[v] = 1;
        }
        for (String e : eq) {
            if (e.charAt(1) == '=') unite(e.charAt(0) - 'a', e.charAt(3) - 'a');
        }
        boolean ok = true;
        for (String e : eq) {
            if (e.charAt(1) == '!' && findRoot(e.charAt(0) - 'a') == findRoot(e.charAt(3) - 'a')) ok = false;
        }
        System.out.println(ok ? "yes" : "no");
    }
}
